 965 :       switch (c) {
 966 :         case '\n': sb.append("\\n"); break;
 967 :         case '\r': sb.append("\\r"); break;
 968 :         case '\t': sb.append("\\t"); break;
 969 :         case '\\': sb.append(backslashEscape); break;
 970 :         case '\"': sb.append(doublequoteEscape); break;
 971 :         case '\'': sb.append(singlequoteEscape); break;
 972 :         case '>':                       // Break --> into --\> or ]]> into ]]\>
 973 :           if (i >= 2 &&
 974 :               ((s.charAt(i - 1) == '-' && s.charAt(i - 2) == '-') ||
 975 :                (s.charAt(i - 1) == ']' && s.charAt(i - 2) == ']'))) {
 976 :             sb.append("\\>");
 977 :           } else {
 978 :             sb.append(c);
 979 :           }
 980 :           break;
 981 :         case '<':
 982 :           // Break </script into <\/script
 983 :           final String END_SCRIPT = "/script";
 984 : 
 985 :           // Break <!-- into <\!--
 986 :           final String START_COMMENT = "!--";
 987 : 
 988 :           if (s.regionMatches(true, i + 1, END_SCRIPT, 0,
 989 :                               END_SCRIPT.length())) {
 990 :             sb.append("<\\");
 991 :           } else if (s.regionMatches(false, i + 1, START_COMMENT, 0,
 992 :                                      START_COMMENT.length())) {
 993 :             sb.append("<\\");
 994 :           } else {
 995 :             sb.append(c);
 996 :           }
 997 :           break;
