 999 :           // If we're given an outputCharsetEncoder, then check if the
1000 :           //  character can be represented in this character set.
1001 :           if (outputCharsetEncoder != null) {
1002 :             if (outputCharsetEncoder.canEncode(c)) {
1003 :               sb.append(c);
1004 :             } else {
1005 :               // Unicode-escape the character.
1006 :               appendHexJavaScriptRepresentation(sb, c);
1007 :             }
1008 :           } else {
1009 :             // No charsetEncoder provided - pass straight latin characters
1010 :             // through, and escape the rest.  Doing the explicit character
1011 :             // check is measurably faster than using the CharsetEncoder.
1012 :             if (c > 0x1f && c <= 0x7f) {
1013 :               sb.append(c);
1014 :             } else {
1015 :               // Other characters can be misinterpreted by some js parsers,
1016 :               // or perhaps mangled by proxies along the way,
1017 :               // so we play it safe and unicode escape them.
1018 :               appendHexJavaScriptRepresentation(sb, c);
1019 :             }
1020 :           }
1021 :       }
1022 :     }
1023 :     sb.append(quote);
1024 :     return sb.toString();
1025 :   }"

