"1141 :   private static void appendHexJavaScriptRepresentation(
1142 :       int codePoint, Appendable out)
1143 :       throws IOException {
1144 :     if (Character.isSupplementaryCodePoint(codePoint)) {
1145 :       // Handle supplementary unicode values which are not representable in
1146 :       // javascript.  We deal with these by escaping them as two 4B sequences
1147 :       // so that they will round-trip properly when sent from java to javascript
1148 :       // and back.
1149 :       char[] surrogates = Character.toChars(codePoint);
1150 :       appendHexJavaScriptRepresentation(surrogates[0], out);
1151 :       appendHexJavaScriptRepresentation(surrogates[1], out);
1152 :       return;
1153 :     }
1154 :     out.append("\\u")
1155 :         .append(HEX_CHARS[(codePoint >>> 12) & 0xf])
1156 :         .append(HEX_CHARS[(codePoint >>> 8) & 0xf])
1157 :         .append(HEX_CHARS[(codePoint >>> 4) & 0xf])
1158 :         .append(HEX_CHARS[codePoint & 0xf]);
